def test_transport_ping_and_idle_do_not_create_math_failure_or_review(self):
        self.clock.value = 200
        for event in ({"type": "tick"}, {"type": "ping"}, {"type": "transport_bytes_received", "bytes": 100}):
            with self.subTest(event=event["type"]):
                rows = observe(self.t, event)
                self.assertFalse(any("review" in r["kind"] or r["kind"] == "self_check_due" for r in rows), rows)

def test_live_operations_can_run_when_work_is_full_and_step_limit_is_reached(self):
        sim = ready_work_sim(3, observation_mode='periodic', observation_interval_seconds=1)
        sim.ports.calls.choose = round_robin()
        continue_reviews(sim)

        def hook(cli, context):
            if context['action']['role'] == 'research_work':
                cli.until(lambda: bool(sim.runtime.get('operational_dispositions')), 'operating slot did not run beside full work')

        install(sim, hook)
        sim.engine.run(max_steps=3)
        operating = [e for e in sim.runtime['executions'].values() if e['role'] == 'operational_review']
        self.assertTrue(operating)
        self.assertFalse([r for r in sim.runtime['reservations'].values()
                          if r['owner_id'] == operating[0]['id'] and r['unit'] == 'execution'])
        self.assertEqual(operating[0]['model'], MODELS['high'])
        if operating[0].get('result_disposition', {}).get('kind') == 'preserved_after_target_change':
            self.assertEqual(sim.runtime['executions'][operating[0]['action']['target']]['status'], 'ended')
        else:
            self.assertEqual(operating[0]['outcome'], 'output_accepted')

def test_pure_validation_rejects_duplicate_list_ids_and_unknown_record_fields(self):
        row = {'id': 'SO-1', 'path': 'input.txt', 'sha256': 'a' * 64}
        for rows, reason in (([row, row], '^record IDs must be globally unique: SO-1$'),
                             ([{**row, 'mystery': True}],
                              r"Additional properties are not allowed \('mystery' was unexpected\)$")):
            with self.subTest(rows=rows), self.assertRaisesRegex(ValueError, reason):
                self.repository.validate_candidate(*current_state({'sources': rows}))
        self.assertIsNone(self.repository._store.read_snapshot().head)
        self.assertEqual(self.backend.writes, [])

def test_mandatory_overflow_reports_size_without_reduction(self):
        with tempfile.TemporaryDirectory() as d:
            context = {'goal': 'x' * 1000, 'recent_history': [1, 2, 3]}
            got = store.fit_context(context, max_bytes=100, workspace=Path(d), mandatory_keys=['goal'])
            self.assertEqual(got['overflow']['reason'], 'mandatory_context_exceeds_limit')
            self.assertEqual(got['context']['goal'], context['goal'])

def test_revoking_research_grants_does_not_stop_a_trust_check(self):
        # Dispatch admits trust checks without a grant; the approved transition is their authority.
        self.assert_case(trust=True, cancel='revoke', stops=False)
